// GeneratedCatalogEvent returns the generated binding for a component/action pair.
func GeneratedCatalogEvent(component, action string) (EventDescriptor, bool) {
	for _, event := range generatedCatalogEvents {
		if event.Component == component && event.Action == action {
			return event, true
		}
	}
	return EventDescriptor{}, false
}

// IsGeneratedCatalogEvent reports whether a component/action pair is registered.
func IsGeneratedCatalogEvent(component, action string) bool {
	_, ok := GeneratedCatalogEvent(component, action)
	return ok
}

// GeneratedCatalogEvents returns a defensive copy of the generated binding.
func GeneratedCatalogEvents() []EventDescriptor {
	return append([]EventDescriptor(nil), generatedCatalogEvents[:]...)
}

